contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint x) public {
        c.sendMoney(address(this), 0, abi.encode(x)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == 0 && c.depositsCount() == 0);
    }
    receive() external payable {}
}

