// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 x) internal {
        try c.sendMoney(address(this), 0, abi.encode(x)) {} catch { return; }
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(c).balance == 0 && c.depositsCount() == 0);
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
